"use client";
import{useCallback,useEffect,useMemo,useState}from"react";import{AppShell}from"../ui/app-shell";import{getSupabaseBrowserClient}from"../../lib/supabase/client";import{usePlayerData}from"../../lib/use-player-data";import{buildDiagnosticObservations,type MissAggregate}from"../../lib/diagnostic-engine";
type LibraryItem={id:string;code:string;title:string;item_type:"golf_drill"|"vector_exercise";purpose:string;dosage:string|null};type SavedCase={id:string;shot_band:string;status:string;confidence:string;pattern_key:string;observation:string;coach_note:string|null;created_at:string;case_recommendations?:Array<{id:string;sequence:number;recommendation_role:string;rationale:string;library_items:LibraryItem|null}>};
export default function DiagnosticsPage(){const{profile,aggregates}=usePlayerData(),[misses,setMisses]=useState<MissAggregate[]>([]),[library,setLibrary]=useState<LibraryItem[]>([]),[cases,setCases]=useState<SavedCase[]>([]),[message,setMessage]=useState("");const canReview=profile?.role==="coach"||profile?.role==="admin";const load=useCallback(async()=>{const sb=getSupabaseBrowserClient();if(!sb||!profile)return;const[shots,items,saved]=await Promise.all([sb.from("detailed_shots").select("shot_band,success,miss_length,miss_direction").eq("player_id",profile.id),sb.from("library_items").select("id,code,title,item_type,purpose,dosage").eq("status","approved"),sb.from("diagnostic_cases").select("id,shot_band,status,confidence,pattern_key,observation,coach_note,created_at,case_recommendations(id,sequence,recommendation_role,rationale,library_items(id,code,title,item_type,purpose,dosage))").eq("player_id",profile.id).order("created_at",{ascending:false})]);const map:Record<string,MissAggregate>={};for(const s of shots.data||[]){const m=map[s.shot_band]||={shot_band:s.shot_band,failures:0,short:0,long:0,left:0,right:0};if(!s.success){m.failures++;if(s.miss_length==="short")m.short++;if(s.miss_length==="long")m.long++;if(s.miss_direction==="left")m.left++;if(s.miss_direction==="right")m.right++}}setMisses(Object.values(map));setLibrary((items.data||[])as LibraryItem[]);setCases((saved.data||[])as unknown as SavedCase[])},[profile]);useEffect(()=>{const timer=setTimeout(()=>void load(),0);return()=>clearTimeout(timer)},[load]);const observations=useMemo(()=>buildDiagnosticObservations(aggregates,misses),[aggregates,misses]);const createCase=async(index:number)=>{const o=observations[index],sb=getSupabaseBrowserClient();if(!sb||!profile||!canReview)return;const{data,error}=await sb.from("diagnostic_cases").insert({player_id:profile.id,shot_band:o.band,status:"draft",confidence:o.confidence,confidence_score:o.confidenceScore,priority_score:o.priorityScore,opportunities:o.opportunities,successes:o.successes,pattern_key:o.patternKey,observation:o.pattern,interpretation:o.interpretation,evidence_summary:o.evidenceSummary,next_test:o.nextTest,guardrail:o.guardrail,created_by:profile.id}).select("id").single();if(error||!data){setMessage(error?.message||"Could not create review.");return}const selected=o.suggestedCodes.map(code=>library.find(item=>item.code===code)).filter(Boolean)as LibraryItem[];if(selected.length)await sb.from("case_recommendations").insert(selected.map((item,i)=>({case_id:data.id,library_item_id:item.id,sequence:i+1,recommendation_role:item.item_type==="vector_exercise"?"physical_support":i===0?"test":"practice",rationale:item.item_type==="vector_exercise"?"Physical support option; use only after movement screening.":i===0?"Establish and classify the pattern before changing technique.":"Progress only if the comparison test supports the hypothesis."})));setMessage("Draft evidence review created. It remains hidden from the player until you approve it.");await load()};const review=async(id:string,status:"approved"|"rejected")=>{const sb=getSupabaseBrowserClient();if(!sb||!profile)return;const{error}=await sb.from("diagnostic_cases").update({status,reviewed_by:profile.id,reviewed_at:new Date().toISOString()}).eq("id",id);setMessage(error?error.message:`Recommendation ${status}.`);if(!error)await load()};return <AppShell active="diagnostics"><header className="page-heading"><div><p className="eyebrow">Package 7E.2</p><h1>Evidence before prescription.</h1><p>The engine ranks scoring signals and describes repeatable outcomes. It never claims a swing or body cause without a coach-led comparison test.</p></div></header>{message&&<div className="success-banner" role="status">{message}</div>}{canReview?<><section className="evidence-summary"><div><strong>{observations.length}</strong><span>Observed shot bands</span></div><div><strong>{observations.filter(o=>o.confidence==="moderate"||o.confidence==="strong").length}</strong><span>Usable evidence signals</span></div><div><strong>{cases.filter(c=>c.status==="draft").length}</strong><span>Awaiting coach decision</span></div></section><div className="diagnostic-layout"><section className="evidence-list">{observations.map((o,i)=><article className="evidence-card" key={o.band}><header><div><p className="eyebrow">Priority {String(i+1).padStart(2,"0")} · {o.band}</p><h2>{o.pattern}</h2></div><span className={`confidence ${o.confidence}`}>{o.confidence} · {o.confidenceScore}%</span></header><p className="evidence-line">{o.evidenceSummary}</p><div className="evidence-grid"><div><small>Observation</small><p>{o.interpretation}</p></div><div><small>Next test</small><p>{o.nextTest}</p></div></div><div className="guardrail"><strong>Diagnostic guardrail</strong><span>{o.guardrail}</span></div><div className="suggestions"><span>Suggested route</span>{o.suggestedCodes.map(code=>{const item=library.find(l=>l.code===code);return item?<div key={code}><b>{code}</b><span>{item.title}</span><small>{item.dosage||"Coach-defined dose"}</small></div>:null})}</div><button className="primary-action" disabled={o.confidence==="insufficient"} onClick={()=>createCase(i)}>{o.confidence==="insufficient"?"Collect more evidence":"Create coach review"}</button></article>)}{!observations.length&&<div className="empty-state compact"><h2>No evidence yet</h2><p>Record a round to create the first scoring observation.</p></div>}</section><aside className="review-queue"><p className="eyebrow">Coach review queue</p><h2>Decisions</h2><p>Players see only approved recommendations.</p>{cases.map(item=><article key={item.id}><strong>{item.shot_band}</strong><span>{item.observation}</span><small>{item.confidence} evidence · {item.status}</small>{item.status==="draft"&&<div><button onClick={()=>review(item.id,"approved")}>Approve</button><button onClick={()=>review(item.id,"rejected")}>Reject</button></div>}</article>)}{!cases.length&&<p className="empty-copy">No saved reviews yet.</p>}</aside></div></>:<section className="evidence-list">{cases.map(item=><article className="evidence-card" key={item.id}><header><div><p className="eyebrow">Coach-approved prescription · {item.shot_band}</p><h2>{item.observation}</h2></div><span className={`confidence ${item.confidence}`}>{item.confidence}</span></header><div className="suggestions"><span>Your practice route</span>{(item.case_recommendations||[]).sort((a,b)=>a.sequence-b.sequence).map(rec=>rec.library_items?<div key={rec.id}><b>{rec.library_items.code}</b><span>{rec.library_items.title}</span><small>{rec.library_items.dosage||"Coach-defined dose"}</small></div>:null)}</div>{item.coach_note&&<p>{item.coach_note}</p>}</article>)}{!cases.length&&<div className="empty-state compact"><h2>No approved prescription yet</h2><p>Your coach will review the evidence before recommendations appear here.</p></div>}</section>}</AppShell>}
